//! XLSX <-> CSV: a workbook generated by `rust_xlsxwriter` (the reference
//! writer) and the csv-json rows; ours against `calamine` (read) and
//! `rust_xlsxwriter` (write), each paired with the `csv` crate.

use std::fs::File;
use std::io::{BufReader, BufWriter};

use sublime::converters::csv_to_xlsx::CSV_TO_XLSX;
use sublime::converters::xlsx_to_csv::XLSX_TO_CSV;

use crate::common::{parse_rows, run_ours};

pub fn run(mode: &str, args: &[String]) -> Result<(), String> {
    match (mode, args) {
        ("gen-xlsx", [rows, path]) => generate_xlsx(rows, path),
        ("ours-xlsx-csv", [input, output]) => run_ours(&XLSX_TO_CSV, input, output),
        ("ours-csv-xlsx", [input, output]) => run_ours(&CSV_TO_XLSX, input, output),
        ("crates-xlsx-csv", [input, output]) => crates_xlsx_to_csv(input, output),
        ("crates-csv-xlsx", [input, output]) => crates_csv_to_xlsx(input, output),
        _ => Err(
            "xlsx-csv modes: gen-xlsx <rows> <path> | ours-xlsx-csv <in> <out> | ours-csv-xlsx <in> <out> | crates-xlsx-csv <in> <out> | crates-csv-xlsx <in> <out>"
                .to_string(),
        ),
    }
}

/// The csv-json record shape as a workbook: strings, numbers, and a date.
fn generate_xlsx(rows: &str, path: &str) -> Result<(), String> {
    let count = parse_rows(rows)?;
    let mut workbook = rust_xlsxwriter::Workbook::new();
    let sheet = workbook.add_worksheet();
    let date_format = rust_xlsxwriter::Format::new().set_num_format("yyyy-mm-dd");
    let headers = ["id", "name", "email", "city", "score", "created", "note"];
    for (column, header) in headers.iter().enumerate() {
        sheet
            .write_string(0, column as u16, *header)
            .map_err(|error| error.to_string())?;
    }
    for index in 0..count {
        let row = (index + 1) as u32;
        let note = if index % 7 == 0 {
            "quoted, with comma"
        } else {
            "plain"
        };
        sheet
            .write_number(row, 0, index as f64)
            .map_err(|error| error.to_string())?;
        sheet
            .write_string(row, 1, format!("user{index}"))
            .map_err(|error| error.to_string())?;
        sheet
            .write_string(row, 2, format!("user{index}@example.com"))
            .map_err(|error| error.to_string())?;
        sheet
            .write_string(row, 3, format!("City{}", index % 1000))
            .map_err(|error| error.to_string())?;
        sheet
            .write_number(row, 4, ((index * 37) % 100) as f64 + 0.5)
            .map_err(|error| error.to_string())?;
        sheet
            .write_number_with_format(row, 5, 45_000.0 + (index % 365) as f64, &date_format)
            .map_err(|error| error.to_string())?;
        sheet
            .write_string(row, 6, note)
            .map_err(|error| error.to_string())?;
    }
    workbook.save(path).map_err(|error| error.to_string())
}

fn crates_xlsx_to_csv(input: &str, output: &str) -> Result<(), String> {
    use calamine::{Data, Reader};
    let mut workbook: calamine::Xlsx<BufReader<File>> =
        calamine::open_workbook(input).map_err(|error: calamine::XlsxError| error.to_string())?;
    let range = workbook
        .worksheet_range_at(0)
        .ok_or("no sheet")?
        .map_err(|error| error.to_string())?;
    let out = File::create(output).map_err(|error| error.to_string())?;
    let mut writer = csv::Writer::from_writer(BufWriter::new(out));
    for row in range.rows() {
        let cells: Vec<String> = row
            .iter()
            .map(|cell| match cell {
                Data::Empty => String::new(),
                Data::String(text) => text.clone(),
                Data::Float(number) => number.to_string(),
                Data::Int(number) => number.to_string(),
                Data::Bool(flag) => flag.to_string().to_uppercase(),
                Data::DateTime(value) => value
                    .as_datetime()
                    .map(|when| when.date().to_string())
                    .unwrap_or_else(|| value.to_string()),
                other => other.to_string(),
            })
            .collect();
        writer
            .write_record(&cells)
            .map_err(|error| error.to_string())?;
    }
    writer.flush().map_err(|error| error.to_string())
}

fn crates_csv_to_xlsx(input: &str, output: &str) -> Result<(), String> {
    let file = File::open(input).map_err(|error| error.to_string())?;
    let mut reader = csv::ReaderBuilder::new()
        .has_headers(false)
        .from_reader(BufReader::new(file));
    let mut workbook = rust_xlsxwriter::Workbook::new();
    let sheet = workbook.add_worksheet();
    let mut record = csv::StringRecord::new();
    let mut row: u32 = 0;
    while reader
        .read_record(&mut record)
        .map_err(|error| error.to_string())?
    {
        for (column, cell) in record.iter().enumerate() {
            match cell.parse::<f64>() {
                Ok(number)
                    if !cell.is_empty() && sublime::io::xlsx::writer::is_number_literal(cell) =>
                {
                    sheet
                        .write_number(row, column as u16, number)
                        .map_err(|error| error.to_string())?;
                }
                _ => {
                    if !cell.is_empty() {
                        sheet
                            .write_string(row, column as u16, cell)
                            .map_err(|error| error.to_string())?;
                    }
                }
            }
        }
        row += 1;
    }
    workbook.save(output).map_err(|error| error.to_string())
}
